#!/usr/bin/env python3
# ── GENERATED by matsci-kb-kit build/build_kit.py — DO NOT EDIT (真源见 kit.yaml) ──
# -*- coding: utf-8 -*-
"""lit_journals.py — 维护期刊白名单（多学科池 → 本库 tier 白名单）

为什么单独做一件事：
    tier 白名单是 lit-watch 的**范围边界**，又要由非材料专业的用户自助扩容。
    让人手抄 ISSN 一定会错，所以这里统一走 OpenAlex 按刊名解析 issn_l，
    并把结果写回 <知识库>/lit-watch/lit_config.yaml 的 `journals:` 段。

用法（工作目录 = 库根）
----
    python tools/lit_journals.py --groups                        # 看领域池里有哪些组
    python tools/lit_journals.py --pool-list materials-chemistry-energy
    python tools/lit_journals.py --from-pool materials-chemistry-energy --only-tier T0,T1
    python tools/lit_journals.py --from-pool biology-medicine --apply
    python tools/lit_journals.py --add "Nature Medicine" "Cell" --tier T0 --apply
    python tools/lit_journals.py --remove "Small"
    python tools/lit_journals.py --resolve-missing --apply       # 补齐空 issn_l
    python tools/lit_journals.py --list
    python tools/lit_journals.py --selftest

约定
----
· 默认干跑（只打印将要发生的变化），确认无误再加 --apply。
· 写回时**只重写 `journals:` 段**，其余内容（注释、tiers、paths…）原样保留；
  但 journals 段内部原有的注释会在重排时丢失。
· 白名单超过 90 刊时会提示分片：OpenAlex 的 source.id OR 列表上限 100，
  lit_discover 已实现 90/片自动分片合并，所以这只是一条提醒而不是错误。
"""
from __future__ import annotations

import argparse
import difflib
import json
import os
import re
import sys
import urllib.parse
import urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import kb_lib as K                                        # noqa: E402

POOL_NAME = "journals-multidisciplinary.yaml"
TIER_ORDER = ["T0", "T1", "T2", "T3", "T4"]
SHARD_HINT = 90


# ---------------------------------------------------------------- 池与配置定位

def pool_path():
    """池文件：优先知识库内的 copies，其次 kit 的 config/ 目录。"""
    cands = [
        os.path.join(K.VAULT, "tools", POOL_NAME),      # 库内（推荐：随库走）
        os.path.join(os.path.dirname(HERE), "lit-watch", POOL_NAME),
    ]
    for p in cands:
        if os.path.exists(p):
            return p
    return cands[-1]


def load_pool(path=None):
    p = path or pool_path()
    if not os.path.exists(p):
        raise SystemExit(f"[!] 找不到期刊池文件: {p}")
    import yaml
    with open(p, encoding="utf-8-sig") as f:
        data = yaml.safe_load(f) or {}
    return data.get("groups") or {}, p, "pyyaml"


def cfg_path():
    return K.LIT_CONFIG_PATH


def load_journals(path=None):
    """读当前白名单，返回 [{issn_l, name, tier}, ...]（保持文件顺序）。"""
    p = path or cfg_path()
    if not os.path.exists(p):
        raise SystemExit(f"[!] 配置不存在: {p}\n    先跑: python scripts/lit_init.py --kb <知识库路径>")
    import yaml
    with open(p, encoding="utf-8-sig") as f:
        data = yaml.safe_load(f) or {}
    out = []
    for j in data.get("journals") or []:
        if isinstance(j, dict):
            out.append({"issn_l": str(j.get("issn_l") or "").strip(),
                        "name": str(j.get("name") or "").strip(),
                        "tier": str(j.get("tier") or data.get("default_tier") or "T3").strip()})
        elif isinstance(j, str):
            out.append({"issn_l": "", "name": j.strip(), "tier": "T3"})
    return out


def render_journals_block(journals, indent="  "):
    """生成 `journals:` 段文本（按 tier、再按刊名排序）。"""
    lines = ["journals:"]
    if not journals:
        return "journals: []\n"
    for tier in TIER_ORDER + sorted({j["tier"] for j in journals} - set(TIER_ORDER)):
        group = [j for j in journals if j["tier"] == tier]
        if not group:
            continue
        lines.append(f"{indent}# ---- {tier} ----")
        for j in sorted(group, key=lambda x: x["name"].lower()):
            issn = j["issn_l"] or ""
            lines.append(f'{indent}- {{issn_l: "{issn}", name: "{j["name"]}", tier: {tier}}}')
    return "\n".join(lines) + "\n"


def write_journals(journals, path=None, backup=True):
    """把 journals 段替换进配置文件，其余内容不动。返回 (path, n_before, n_after)。

    ⚠️ 本库的 `journals:` 段里有人工维护的分级小节与注释，**重排会丢掉段内注释**，
    所以写盘前默认先备份成 `lit_config.yaml.bak-<时间戳>`（同目录），出问题可直接换回。
    """
    p = path or cfg_path()
    text = K.read_text(p)
    if backup:
        import datetime as _dt
        bk = p + ".bak-" + _dt.datetime.now().strftime("%Y%m%d-%H%M%S")
        with open(bk, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
    lines = text.split("\n")
    start = None
    for i, ln in enumerate(lines):
        if re.match(r"^journals\s*:", ln):
            start = i
            break
    if start is None:
        raise SystemExit(f"[!] 配置里没有顶层 `journals:` 段: {p}")
    end = start + 1
    while end < len(lines):
        ln = lines[end]
        if ln.strip() and not ln.startswith((" ", "\t", "#")):
            break
        if ln.startswith("#") and end > start + 1:
            # 顶层注释：视为段落边界（保留注释在原地）
            break
        end += 1
    new_block = render_journals_block(journals)
    out = "\n".join(lines[:start]) + ("\n" if start else "") + new_block + "\n".join(lines[end:])
    with open(p, "w", encoding="utf-8", newline="\n") as f:
        f.write(out)
    return p, len(lines), len(out.split("\n"))


# ---------------------------------------------------------------- OpenAlex

def _oa_get(url, timeout=25):
    req = urllib.request.Request(url, headers={
        "User-Agent": "lit-watch-workflow/1.0 (+https://openalex.org)",
        "Accept": "application/json",
    })
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.loads(r.read().decode("utf-8", errors="replace"))


def resolve_journal(name, mailto="", verbose=True):
    """按刊名在 OpenAlex 查 issn_l。返回 {name, issn_l, openalex_name} 或 None。"""
    q = urllib.parse.urlencode({"search": name, "per-page": 5})
    url = f"https://api.openalex.org/sources?{q}"
    if mailto:
        url += "&mailto=" + urllib.parse.quote(mailto)
    try:
        data = _oa_get(url)
    except Exception as e:                                   # noqa: BLE001
        if verbose:
            print(f"    [!] 查询失败 {name}: {e}")
        return None
    best, best_ratio = None, 0.0
    want = re.sub(r"[^a-z0-9]+", " ", name.lower()).strip()
    for row in data.get("results") or []:
        disp = row.get("display_name") or ""
        got = re.sub(r"[^a-z0-9]+", " ", disp.lower()).strip()
        ratio = difflib.SequenceMatcher(None, want, got).ratio()
        ranked = ratio + (0.25 if disp.lower() == name.lower() else 0.0)
        if row.get("type") == "journal":
            ranked += 0.05
        if ranked > best_ratio:
            best, best_ratio = row, ranked
    if not best or best_ratio < 0.72:
        if verbose:
            got = (best or {}).get("display_name")
            print(f"    [?] 无法可靠匹配「{name}」" + (f"（最接近：{got}）" if got else ""))
        return None
    issn = (best.get("issn_l") or "").strip()
    if not issn:
        if verbose:
            print(f"    [?] 「{best.get('display_name')}」没有 issn_l，跳过")
        return None
    return {"name": name, "issn_l": issn, "openalex_name": best.get("display_name")}


# ---------------------------------------------------------------- 增删

def merge(existing, additions, verbose=True):
    """按 issn_l（优先）或刊名去重合并；返回 (结果, 新增数, 更新数)。"""
    by_issn = {j["issn_l"].lower(): j for j in existing if j["issn_l"]}
    by_name = {j["name"].lower(): j for j in existing if j["name"]}
    out = list(existing)
    added = updated = 0
    for a in additions:
        hit = (by_issn.get(a["issn_l"].lower()) if a.get("issn_l") else None) \
            or by_name.get(a["name"].lower())
        if hit:
            if a.get("tier") and a["tier"] != hit["tier"]:
                if verbose:
                    print(f"    [tier] {hit['name']}: {hit['tier']} → {a['tier']}")
                hit["tier"] = a["tier"]
                updated += 1
            if a.get("issn_l") and not hit["issn_l"]:
                hit["issn_l"] = a["issn_l"]
                updated += 1
            continue
        out.append({"issn_l": a.get("issn_l", ""), "name": a["name"],
                    "tier": a.get("tier") or "T3"})
        if a.get("issn_l"):
            by_issn[a["issn_l"].lower()] = out[-1]
        by_name[a["name"].lower()] = out[-1]
        added += 1
    return out, added, updated


def summarize(journals):
    tiers = {}
    for j in journals:
        tiers[j["tier"]] = tiers.get(j["tier"], 0) + 1
    no_issn = [j["name"] for j in journals if not j["issn_l"]]
    print(f"  白名单合计 {len(journals)} 刊：" +
          "  ".join(f"{t}={tiers.get(t, 0)}" for t in TIER_ORDER) +
          f"  未解析 issn_l: {len(no_issn)}")
    if no_issn:
        print(f"    未解析：{', '.join(no_issn[:6])}{' …' if len(no_issn) > 6 else ''}")
        print("    → 跑 `--resolve-missing --apply` 用 OpenAlex 补齐")
    if len(journals) > SHARD_HINT:
        print(f"  [提示] 超过 {SHARD_HINT} 刊：lit_discover 会按 90/片自动分片检索，"
              "速度略慢属正常（OpenAlex 的 OR 列表上限 100）。")


# ---------------------------------------------------------------- 自检

def selftest():
    ok = fail = 0

    def chk(name, cond, extra=""):
        nonlocal ok, fail
        if cond:
            ok += 1
            print(f"  [ok  ] {name}")
        else:
            fail += 1
            print(f"  [FAIL] {name} {extra}")

    print("=== lit_journals --selftest ===")
    groups, p, backend = load_pool()
    chk("期刊池可加载（tools/journals-multidisciplinary.yaml）", bool(groups), p)
    chk("池覆盖 8 个领域组", len(groups) >= 6, f"实际 {len(groups)} 组")
    chk("池含多学科组（材料/生命/CS/物理/工程/环境/社科）",
        all(g in groups for g in ("materials-chemistry-energy", "biology-medicine",
                                  "cs-ai-ml", "physics-optics", "engineering",
                                  "environment-earth-energy")))
    total = sum(len(g.get("journals") or []) for g in groups.values())
    chk("池内期刊数 > 100", total > 100, f"实际 {total}")

    # 渲染 → 解析 往返（用 pyyaml）
    import yaml
    demo = [{"issn_l": "0028-0836", "name": "Nature", "tier": "T0"},
            {"issn_l": "", "name": "Cell", "tier": "T0"}]
    block = "dummy: 1\n" + render_journals_block(demo)
    parsed = (yaml.safe_load(block) or {}).get("journals")
    keyf = lambda xs: sorted(xs or [], key=lambda x: x["name"].lower())      # noqa: E731
    chk("journals 段渲染后可被解析回",
        keyf(parsed) == keyf(demo), json.dumps(parsed, ensure_ascii=False))

    # 合并去重：同一 issn 的第二次出现不得新增，只更新 tier
    ex = [{"issn_l": "0028-0836", "name": "Nature", "tier": "T1"}]
    merged, added, updated = merge(ex, [{"issn_l": "0028-0836", "name": "Nature (dup)",
                                         "tier": "T0"}], verbose=False)
    chk("按 issn 去重且更新 tier", len(merged) == 1 and merged[0]["tier"] == "T0"
        and added == 0 and updated == 1)
    merged2, added2, _ = merge(ex, [{"issn_l": "", "name": "nature", "tier": "T0"}], verbose=False)
    chk("刊名大小写不敏感去重", len(merged2) == 1 and added2 == 0)

    # 池内不得有空白/控制字符（写入配置的正则）
    bad = []
    for gname, g in groups.items():
        for j in g.get("journals") or []:
            if not j.get("name") or re.search(r"[\u200b-\u200f\ufeff]", j["name"]):
                bad.append((gname, j.get("name")))
    chk("池内刊名无零宽字符/空值", not bad, str(bad[:3]))

    print(f"\n{'SELFTEST PASSED' if fail == 0 else 'SELFTEST FAILED'}: {ok}/{ok + fail}")
    return 0 if fail == 0 else 1


# ---------------------------------------------------------------- CLI

def main():
    ap = argparse.ArgumentParser(description="维护 lit-watch 期刊白名单（多学科池 → tier 白名单）")
    ap.add_argument("--config", default="", help="lit_config.yaml 路径（默认 <知识库>/lit-watch/lit_config.yaml）")
    ap.add_argument("--pool", default="", help="期刊池文件（默认 kit 的 config/journals-multidisciplinary.yaml）")
    ap.add_argument("--groups", action="store_true", help="列出池里的领域组")
    ap.add_argument("--pool-list", default="", help="列出某组内的期刊")
    ap.add_argument("--from-pool", default="", help="把某组（可逗号分隔）加入白名单")
    ap.add_argument("--only-tier", default="", help="配合 --from-pool 只取指定档，如 T0,T1")
    ap.add_argument("--add", nargs="*", default=[], help="按刊名新增（OpenAlex 解析 issn_l）")
    ap.add_argument("--tier", default="T3", help="配合 --add 指定档位（默认 T3）")
    ap.add_argument("--remove", nargs="*", default=[], help="按刊名或 issn_l 删除")
    ap.add_argument("--resolve-missing", action="store_true", help="为缺失 issn_l 的条目解析")
    ap.add_argument("--list", action="store_true", help="列出当前白名单")
    ap.add_argument("--apply", action="store_true", help="真正写盘（默认干跑）")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        return selftest()
    if args.pool:
        os.environ["LITWATCH_POOL"] = args.pool
    cfg_file = args.config or cfg_path()

    if args.groups:
        groups, p, backend = load_pool(args.pool or None)
        print(f"期刊池: {p}  （解析后端: {backend}）")
        for gname, g in groups.items():
            n = len(g.get("journals") or [])
            print(f"  {gname:34} {n:3} 刊   {g.get('label', '')}")
        return 0

    if args.pool_list:
        groups, p, _ = load_pool(args.pool or None)
        g = groups.get(args.pool_list)
        if not g:
            raise SystemExit(f"[!] 没有这个组: {args.pool_list}")
        for j in g.get("journals") or []:
            print(f"  {j.get('tier', '?'):3} {j.get('name', ''):52} {j.get('issn_l') or '(待解析)'}")
        return 0

    journals = load_journals(cfg_file)
    changed = False

    if args.remove:
        targets = {t.lower() for t in args.remove}
        keep = [j for j in journals if j["name"].lower() not in targets
                and j["issn_l"].lower() not in targets]
        print(f"[删除] {len(journals) - len(keep)} 条")
        journals, changed = keep, changed or len(keep) != len(journals)

    if args.from_pool:
        groups, p, _ = load_pool(args.pool or None)
        picks = []
        for gname in [x.strip() for x in args.from_pool.split(",") if x.strip()]:
            g = groups.get(gname)
            if not g:
                raise SystemExit(f"[!] 没有这个组: {gname}（用 --groups 看全部）")
            picks.extend(g.get("journals") or [])
        if args.only_tier:
            want = {t.strip().upper() for t in args.only_tier.split(",")}
            picks = [j for j in picks if str(j.get("tier", "")).upper() in want]
        journals, added, updated = merge(journals, picks)
        print(f"[池] {args.from_pool}: 新增 {added} 条，更新 {updated} 条")
        changed = changed or bool(added or updated)

    if args.add:
        mailto = ""
        try:
            cfg = K.load_lit_config(cfg_file)
            mailto = (cfg.get("datasource") or {}).get("mailto") or ""
        except Exception:                                    # noqa: BLE001
            pass
        resolved = []
        print(f"[解析] OpenAlex 查询 {len(args.add)} 个刊名 …")
        for name in args.add:
            r = resolve_journal(name, mailto=mailto)
            if r:
                r["tier"] = args.tier
                print(f"    [ok ] {name} → {r['openalex_name']}  issn_l={r['issn_l']}")
                resolved.append(r)
        journals, added, updated = merge(journals, resolved)
        print(f"[新增] {added} 条，更新 {updated} 条")
        changed = changed or bool(added or updated)

    if args.resolve_missing:
        missing = [j for j in journals if not j["issn_l"]]
        mailto = ""
        try:
            cfg = K.load_lit_config(cfg_file)
            mailto = (cfg.get("datasource") or {}).get("mailto") or ""
        except Exception:                                    # noqa: BLE001
            pass
        print(f"[解析] {len(missing)} 条缺 issn_l，逐个查 OpenAlex …")
        resolved = []
        for j in missing:
            r = resolve_journal(j["name"], mailto=mailto)
            if r:
                r["tier"] = j["tier"]
                print(f"    [ok ] {j['name']} → issn_l={r['issn_l']}")
                resolved.append(r)
        journals, added, updated = merge(journals, resolved)
        print(f"[解析] 补齐 {added} 条")
        changed = changed or bool(added)

    if args.list:
        for t in TIER_ORDER:
            group = [j for j in journals if j["tier"] == t]
            if not group:
                continue
            print(f"--- {t} ({len(group)}) ---")
            for j in sorted(group, key=lambda x: x["name"].lower()):
                print(f"  {j['name']:52} {j['issn_l'] or '(待解析)'}")
        summarize(journals)
        return 0

    summarize(journals)
    if not changed:
        print("（没有变化）")
        return 0
    if args.apply:
        p, n0, n1 = write_journals(journals, cfg_file)
        print(f"[写入] {p}（{n0} → {n1} 行）")
        print("        下一步：`--list` 复核，或直接跑 lit_discover 试试命中。")
    else:
        print("（干跑结束，确认后加 --apply 写盘）")
    return 0


if __name__ == "__main__":
    sys.exit(main())
